theme.css:
/* ==== INTERFACE ====
   token  --bg #F1F6F8              冷调画布底色｜全页背景
   token  --surface #FFFFFF         信息承载面｜仅面板、输入与媒体底
   token  --text #102A36            主文字｜标题、正文、关键结构线
   token  --muted #4E6874           次级文字与结构线｜说明、轮廓、坐标轴
   token  --focus #D9571F           当前焦点｜选中态、主按钮、当前步骤
   token  --member #236A94          单个基学习器｜模型节点、单模型预测
   token  --ensemble #123F5A        集成结果｜聚合节点、最终预测
   token  --sample #3B7555          样本机制｜重采样、样本权重、数据流
   token  --correct #24704C         判定正确｜仅反馈与校验
   token  --incorrect #A44037       判定错误｜仅反馈与校验
   token  --font-sans Noto Sans CJK SC  展示与正文｜中文课堂投影
   token  --font-num DIN Alternate  数值｜读数、刻度、代码式短数字
   token  --fs-h1 34px              页标题
   token  --fs-h2 22px              区块标题
   token  --fs-lead 19px            导语
   token  --fs-body 18px            正文
   token  --fs-sec 16px             次级成句说明
   token  --fs-label 15px           控件、图例与标签
   token  --fs-tick 13px            纯数字刻度
   token  --r-sm 8px                小控件圆角
   token  --r-md 14px               面板与媒体圆角
   token  --line 2px                投影可见结构线
   token  --ease cubic-bezier(.2,.8,.2,1)  状态过渡
   token  --dur 180ms               状态过渡时长
   版心   1488×844                  #stage 已含 56px×28px padding
   版式   #stage                    纵向舞台；主内容区由页面设 flex:1
   签名   .vote-stack               错位叠放的学习器票片；用于成员到聚合的重复母题
   组件   .big/.big.sm/.big.lg      主读数及尺寸变体
   组件   .num/.unit                等宽数字与单位
   组件   .hint                     操作提示
   组件   .btn/.btns                按钮与按钮组；支持选中、禁用
   组件   .ctl 及 range             控件行与范围输入
   组件   .tag                      分类标签
   组件   .legend>.li>.sw           图例项、色块与线样
   组件   .cvbox                    媒体定位、裁切与圆角
   组件   .quiz/.opt/.fb            作答容器、选项与反馈
   组件   .lead/.small/.note        导语、次级成句与注记
   组件   .panel/.panel.q           填色仪器面板与无填色等边距面板
   组件   .backdrop/.backdrop-note  仅整页底图时使用
   ==== /INTERFACE ==== */

:root { --pad-x: 56px; --pad-y: 28px; }

:root {
  --bg: #F1F6F8;
  --surface: #FFFFFF;
  --text: #102A36;
  --muted: #4E6874;
  --focus: #D9571F;
  --member: #236A94;
  --ensemble: #123F5A;
  --sample: #3B7555;
  --correct: #24704C;
  --incorrect: #A44037;
  --font-sans: "Noto Sans CJK SC", "Source Han Sans SC", "Microsoft YaHei", sans-serif;
  --font-num: "DIN Alternate", "Aptos Narrow", "Noto Sans CJK SC", sans-serif;
  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;
  --r-sm: 8px;
  --r-md: 14px;
  --line: 2px;
  --ease: cubic-bezier(.2,.8,.2,1);
  --dur: 180ms;
}

/* 基础 */
html,
body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.5;
}

#stage { display: flex; flex-direction: column; padding: var(--pad-y) var(--pad-x); }

h1,
h2,
h3,
p {
  margin: 0;
}

h1 {
  font-size: var(--fs-h1);
  line-height: 1.18;
  font-weight: 760;
  letter-spacing: -.02em;
}

h2 {
  font-size: var(--fs-h2);
  line-height: 1.3;
  font-weight: 720;
}

button,
input {
  font: inherit;
}

/* 数值 */
.big {
  color: var(--ensemble);
  font-family: var(--font-num);
  font-size: 52px;
  font-weight: 750;
  line-height: 1;
  font-variant-numeric: tabular-nums lining-nums;
  letter-spacing: -.025em;
}

.big.sm { font-size: 40px; }
.big.lg { font-size: 68px; }

.num {
  font-family: var(--font-num);
  font-variant-numeric: tabular-nums lining-nums;
  font-weight: 700;
}

.unit {
  margin-inline-start: .3em;
  color: var(--muted);
  font-size: var(--fs-label);
  font-weight: 650;
}

/* 操作 */
.hint {
  color: var(--muted);
  font-size: var(--fs-sec);
  line-height: 1.45;
}

.btns {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

.btn {
  min-height: 44px;
  padding: 9px 16px;
  border: var(--line) solid var(--ensemble);
  border-radius: var(--r-sm);
  background: transparent;
  color: var(--ensemble);
  font-size: var(--fs-label);
  font-weight: 720;
  cursor: pointer;
  transition: background-color var(--dur) var(--ease), color var(--dur) var(--ease), border-color var(--dur) var(--ease), transform var(--dur) var(--ease);
}

.btn:hover { background: #E4EEF3; }
.btn:active { transform: translateY(1px); }

.btn[aria-pressed="true"],
.btn.is-selected {
  border-color: var(--focus);
  background: var(--focus);
  color: var(--surface);
}

.btn:disabled,
.btn[aria-disabled="true"] {
  border-color: var(--muted);
  color: var(--muted);
  cursor: not-allowed;
  opacity: .58;
  transform: none;
}

.ctl {
  display: flex;
  align-items: center;
  gap: 14px;
  color: var(--text);
  font-size: var(--fs-label);
  font-weight: 650;
}

.ctl input[type="range"] {
  width: 220px;
  height: 28px;
  margin: 0;
  accent-color: var(--focus);
  cursor: pointer;
}

.ctl input[type="range"]:disabled {
  cursor: not-allowed;
  opacity: .55;
}

/* 标记 */
.tag {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 3px 10px;
  border: var(--line) solid var(--muted);
  border-radius: 999px;
  color: var(--text);
  font-size: var(--fs-label);
  font-weight: 680;
  line-height: 1.25;
  white-space: nowrap;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 18px;
  color: var(--muted);
  font-size: var(--fs-label);
}

.legend > .li {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.sw {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  border: var(--line) solid currentColor;
  border-radius: 4px;
  background: currentColor;
}

.sw.line {
  width: 24px;
  height: 0;
  border: 0;
  border-top: var(--line) solid currentColor;
  border-radius: 0;
  background: transparent;
}

/* 媒体 */
.cvbox {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  border-radius: var(--r-md);
}

.cvbox > img,
.cvbox > video,
.cvbox > canvas,
.cvbox > svg {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* 作答 */
.quiz {
  display: grid;
  gap: 12px;
}

.opt {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  min-height: 46px;
  padding: 10px 14px;
  border: var(--line) solid var(--muted);
  border-radius: var(--r-sm);
  background: transparent;
  color: var(--text);
  font-size: var(--fs-sec);
  line-height: 1.4;
  cursor: pointer;
  transition: border-color var(--dur) var(--ease), background-color var(--dur) var(--ease);
}

.opt:hover { background: #E8F0F4; }

.opt[aria-checked="true"],
.opt.is-selected {
  border-color: var(--focus);
  background: #FFF0E8;
}

.opt.is-correct {
  border-color: var(--correct);
  background: #E8F3ED;
}

.opt.is-incorrect {
  border-color: var(--incorrect);
  background: #F8EAE8;
}

.fb {
  min-height: 24px;
  color: var(--text);
  font-size: var(--fs-sec);
  line-height: 1.45;
}

.fb.is-correct { color: var(--correct); }
.fb.is-incorrect { color: var(--incorrect); }

/* 文字 */
.lead {
  color: var(--text);
  font-size: var(--fs-lead);
  line-height: 1.5;
}

.small {
  color: var(--muted);
  font-size: var(--fs-sec);
  line-height: 1.45;
}

.note {
  padding-inline-start: 14px;
  border-inline-start: var(--line) solid var(--muted);
  color: var(--muted);
  font-size: var(--fs-sec);
  line-height: 1.45;
}

/* 仪器 */
.panel {
  padding: 18px;
  border: var(--line) solid #C1D0D7;
  border-radius: var(--r-md);
  background: var(--surface);
  box-shadow: 0 3px 10px rgba(16, 42, 54, .08);
}

.panel.q {
  background: transparent;
  box-shadow: none;
}

/* 集成签名：错位票片 */
.vote-stack {
  position: relative;
  isolation: isolate;
}

.vote-stack::before,
.vote-stack::after {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 0;
  border: var(--line) solid var(--member);
  border-radius: var(--r-sm);
  background: var(--surface);
}

.vote-stack::before { transform: translate(-8px, 8px); opacity: .72; }
.vote-stack::after { transform: translate(-16px, 16px); opacity: .38; }

/* 整页底图 */
.backdrop {
  position: absolute;
  inset: 0;
  z-index: -1;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(.72) contrast(1.08) brightness(.62);
}

.backdrop-note {
  align-self: flex-end;
  padding: 5px 8px;
  border-radius: var(--r-sm);
  background: rgba(16, 42, 54, .86);
  color: #FFFFFF;
  font-size: var(--fs-label);
  line-height: 1.35;
}

svg text { font-family: var(--font-sans); }
svg .bar, svg .cell, svg .box { width:auto; height:auto; }
